const d={"t": "Painting", "y": "FILE 03", "d": "绘画、速写与视觉实验。这里将展示真实画作、创作系列和背后的记录。画作待归档。", "bg": "#292e29", "ink": "#e5dfc8", "big": ["PAINTING"]}; export default {name:d.t,fill:false,cassette:{shell:'clear-pink',drawLabel(g,w,h){g.fillStyle='#efbdd5';g.fillRect(0,0,w,h);g.fillStyle='#68374e';g.globalAlpha=.3;g.fillRect(w*.02,h*.17,w*.008,h*.66);g.globalAlpha=1;g.fillStyle='#68374e';g.font='850 '+h*.4+'px "Noto Sans SC",sans-serif';g.fillText(d.t,w*.055,h*.66);g.font=h*.15+'px monospace';g.textAlign='right';g.fillText(d.y,w*.96,h*.66);g.textAlign='left';}},mount({ctx:g,width:w,height:h}){return {frame(t){g.fillStyle=d.bg;g.fillRect(0,0,w,h);g.strokeStyle='#b18f7366';g.strokeRect(65,65,w-130,h-130);g.fillStyle=d.ink;g.font='24px monospace';g.fillText('PRIVATE COLLECTION / '+d.y,95,120);g.font='600 70px serif';g.fillText(d.t,95,280);g.font='23px sans-serif';let text=d.d, y=360;while(text.length){g.fillText(text.slice(0,27),95,y);text=text.slice(27);y+=42}g.font='20px monospace';g.fillText('PLAY  >  PERSONAL ARCHIVE',95,h-110)},stop(){},input(){}}}};